function solve_board(grid)
{
    let index = 0
    while (index < 81) {
        if (grid[index] == 0) {
            let row = (index / 9) * 9
            let column = index % 9
            let box = (index / 27) * 27 + (column / 3) * 3
            let digit = 1
            while (digit < 10) {
                let valid = true
                let k = 0
                while (k < 9) {
                    if (grid[row + k] == digit or grid[column + k * 9] == digit) {
                        valid = false
                        break
                    }
                    if (grid[box + (k / 3) * 9 + k % 3] == digit) {
                        valid = false
                        break
                    }
                    k = k + 1
                }
                if (valid) {
                    grid[index] = digit
                    if (this(grid)) {
                        return true
                    }
                }
                digit = digit + 1
            }
            grid[index] = 0
            return false
        }
        index = index + 1
    }
    return true
}

